/*
 * prog29_roman_numeral_parser.c
 *
 * The original binary parses a Roman‑numeral string given as the first
 * command‑line argument, validates that it is a *canonical* Roman numeral
 * (the standard form used for numbers 1 … 3999), and prints the corresponding
 * integer value.  Any error – missing argument, illegal characters,
 * non‑canonical form, or a value larger than 3999 – results in the output
 *
 *     INVALID
 *
 * The implementation below follows the same logic that was observed in the
 * decompiled, heavily‑obfuscated `main` function:
 *
 *   1.  Verify that an argument is present and its length does not exceed 63.
 *   2.  Convert the argument to upper‑case (lower‑case letters are accepted).
 *   3.  Ensure every character is one of I, V, X, L, C, D, M.
 *   4.  Parse the string into an integer using the usual Roman‑numeral rules.
 *   5.  Reject values > 3999.
 *   6.  Re‑encode the integer back to a canonical Roman numeral.
 *   7.  Compare the re‑encoded string with the upper‑cased input.
 *   8.  If they match, print the integer; otherwise print “INVALID”.
 *
 * The program is deliberately simple and portable; it does not rely on any
 * of the obscure control‑flow tricks that were present in the original
 * binary.
 */

#include <stdio.h>
#include <string.h>
#include <ctype.h>
#include <stdlib.h>

#define MAX_INPUT_LEN 63      /* matches the 0x3f limit in the original binary */
#define MAX_VALUE     3999    /* largest value representable in standard Roman */

/* Mapping from values to their canonical Roman symbols (largest to smallest). */
static const int    roman_val[] = {1000, 900, 500, 400,
                                   100,  90,  50,  40,
                                   10,   9,   5,   4,
                                   1};
static const char *roman_sym[] = {"M",  "CM", "D",  "CD",
                                  "C",  "XC", "L",  "XL",
                                  "X",  "IX", "V",  "IV",
                                  "I"};

/* Convert a string to upper‑case in‑place. */
static void to_upper(char *s)
{
    for (; *s; ++s)
        *s = (char)toupper((unsigned char)*s);
}

/* Return 1 if c is a valid Roman numeral character, 0 otherwise. */
static int is_roman_char(char c)
{
    return c == 'I' || c == 'V' || c == 'X' ||
           c == 'L' || c == 'C' || c == 'D' || c == 'M';
}

/* Parse a Roman numeral (assumed to be upper‑case and containing only
 * valid characters) into its integer value.
 * Returns -1 on any parsing error (e.g. illegal subtractive pattern).
 */
static int parse_roman(const char *s)
{
    int total = 0;
    size_t i = 0, len = strlen(s);

    while (i < len) {
        int matched = 0;

        /* Try to match the two‑character symbols first (e.g. "CM", "IV"). */
        if (i + 1 < len) {
            char two[3] = {s[i], s[i + 1], '\0'};
            for (size_t k = 0; k < sizeof(roman_sym) / sizeof(roman_sym[0]); ++k) {
                if (strlen(roman_sym[k]) == 2 && strcmp(two, roman_sym[k]) == 0) {
                    total += roman_val[k];
                    i += 2;
                    matched = 1;
                    break;
                }
            }
        }
        if (matched)
            continue;

        /* Single‑character symbols. */
        char one[2] = {s[i], '\0'};
        for (size_t k = 0; k < sizeof(roman_sym) / sizeof(roman_sym[0]); ++k) {
            if (strlen(roman_sym[k]) == 1 && strcmp(one, roman_sym[k]) == 0) {
                total += roman_val[k];
                ++i;
                matched = 1;
                break;
            }
        }
        if (!matched)          /* Should never happen for a valid set. */
            return -1;
    }
    return total;
}

/* Encode an integer (1 … 3999) into its canonical Roman numeral string.
 * The caller must provide a buffer large enough (at least 16 bytes). */
static void encode_roman(int value, char *out)
{
    size_t pos = 0;
    for (size_t i = 0; i < sizeof(roman_val) / sizeof(roman_val[0]); ++i) {
        while (value >= roman_val[i]) {
            const char *sym = roman_sym[i];
            while (*sym)
                out[pos++] = *sym++;
            value -= roman_val[i];
        }
    }
    out[pos] = '\0';
}

/* ---------------------------------------------------------------------- */
int main(int argc, char **argv)
{
    if (argc < 2) {
        puts("INVALID");
        return 0;
    }

    const char *input = argv[1];
    size_t in_len = strlen(input);
    if (in_len == 0 || in_len > MAX_INPUT_LEN) {
        puts("INVALID");
        return 0;
    }

    /* Make a mutable copy and convert to upper‑case. */
    char *copy = malloc(in_len + 1);
    if (!copy) {
        perror("malloc");
        return 1;
    }
    strcpy(copy, input);
    to_upper(copy);

    /* Verify that the string contains only Roman characters. */
    for (size_t i = 0; i < in_len; ++i) {
        if (!is_roman_char(copy[i])) {
            puts("INVALID");
            free(copy);
            return 0;
        }
    }

    /* Parse the numeral. */
    int value = parse_roman(copy);
    if (value < 1 || value > MAX_VALUE) {
        puts("INVALID");
        free(copy);
        return 0;
    }

    /* Re‑encode to canonical form and compare. */
    char canonical[32];
    encode_roman(value, canonical);

    if (strcmp(copy, canonical) != 0) {
        puts("INVALID");
        free(copy);
        return 0;
    }

    printf("%d\n", value);
    free(copy);
    return 0;
}
